insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'english_proficiency', 'IELTS Academic/Online: 6.5 overall, minimum 6.0 in every section', 'For enrollment in Bocconi bachelor''s programs taught in English (level B2 requirement), the official accepted-certificates table lists IELTS Academic and IELTS Online with a minimum overall score of 6.5, with at least 6.0 in every section.', true, 'high', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/english-certificates-accepted-enrollment', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'english_proficiency', 'TOEFL iBT: minimum score of 88', 'For enrollment in Bocconi bachelor''s programs taught in English (level B2 requirement), the official accepted-certificates table lists TOEFL iBT with a minimum score of 88.', true, 'high', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/english-certificates-accepted-enrollment', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'english_proficiency', 'Duolingo English Test: minimum score of 110', 'For enrollment in Bocconi bachelor''s programs taught in English (level B2 requirement), the official accepted-certificates table lists the Duolingo English Test with a minimum score of 110.', true, 'high', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/english-certificates-accepted-enrollment', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'english_proficiency', 'English requirement can be met via certification, Bocconi''s own test, native-speaker status, or a qualifying diploma', '"This requirement can be fullfilled through: English language certification that is to be provided as soon as you obtain it and in any case by the deadline for enrolling" OR "Bocconi English language proficiency test with level B2 or higher" OR "Status of native speaker (English mother tongue). Citizen from a majority English-speaking country (Australia, Canada, New Zealand, United Stated, United Kingdom) are automatically considered to meet the minimum English language requirement" OR "Diplomas awarded in English (i.e. International Baccalaureate Diploma, American High School Diploma, British, Scottish and Irish qualifications, Canadian High School Diploma entirely awarded in English, Baccalauréat Français International (BFI) and European Baccalaureate, Indian diplomas such as CISCE or CBSE)".', true, 'high', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/results-and-enrollment', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'minimum_grade', 'Selection is based on selection-test score (55%) and GPA of the third-last and second-last years (45%)', '"The selection is based on the following elements: 1. Selection test score — 55% ... 2. Third-last and second-last year GPA — 45%." The page confirms "The evaluation of applicants is based solely on these two elements" — mid-year grades, last-year grades, predicted grades, and university grades are explicitly NOT considered.', true, 'high', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/admissions', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'minimum_grade', 'Applicants without valid transcripts default to the minimum passing grade (6/10)', '"Applicants who are NOT able to provide valid transcripts or documentation will enter the selection process with the minimum passing grade (6 out of 10 – Italian system)." GPA is otherwise calculated using a personal calculator available only within the applicant''s own application portal, on a scale of ten.', false, 'high', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/gpa-and-high-school-curriculum', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'minimum_grade', 'IB Diploma applicants need at least 24 points, with 12 at Higher Level', 'For applicants with the International Baccalaureate Diploma specifically: "at least 24 points in six chosen subjects, 12 of which must be obtained at ''Higher Level''", plus "successful passing of the three core subjects: Theory of Knowledge (TOK), Creativity, Action, Service (CAS), and Extended Essay (EE)", to be completed "by no later than the session of May (results available at the beginning of July)".', true, 'high', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/specific-diplomas-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'minimum_grade', 'American High School Diploma applicants need at least 3 AP exams passed with a minimum grade of 3/5', 'For applicants with the American High School Diploma specifically: "at least 3 Advanced Placement (AP) [exams] by July", "passed with a minimum grade of 3 out of 5 within July".', true, 'high', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/specific-diplomas-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'curriculum', 'Bocconi does not set any specific requirement in terms of subjects or tracks taken during secondary school', '"Bocconi University does not set any specific requirement in terms of subjects or tracks taken by applicants during the secondary school."', false, 'high', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/gpa-and-high-school-curriculum', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'curriculum', 'Taking quantitative-based courses (math, physics, business studies, economics) during secondary school might help admitted students', '"students should consider that, if admitted, taking quantitative-based courses/modules during secondary school (math, physics, business studies, economics, etc) might help them" adapt to Bocconi''s programs. Stated as a recommendation, not a formal admission requirement.', false, 'medium', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/gpa-and-high-school-curriculum', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'standardized_test', 'The Bocconi online test lasts 75 minutes and consists of 50 SAT-oriented multiple-choice questions across 4 sections', '"The online Bocconi test lasts 75 minutes." "It consists of 50 multiple-choice questions, designed SAT-oriented": "Mathematics: 24 questions", "Reading comprehension: 11 questions", "Numerical reasoning: 6 questions", "Critical thinking: 9 questions". Up to four test attempts allowed during the availability window.', true, 'high', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/online-bocconi-test', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'standardized_test', 'Scoring is +1 for correct, 0 for missing, −0.2 for wrong; a total below 17 is not considered', '"Scores are calculated as follows: Right answer: 1 point / Missing answer: 0 points / Wrong answer: — 0.2 points." "Applicants who receive a total score (penalties included) lower than 17 will not be considered in the selection process."', true, 'high', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/online-bocconi-test', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b54372b8-c4a7-4d5c-9c33-85a395e6752b', 'standardized_test', 'Bachelor in Mathematical and Computing Sciences for AI requires at least 11/24 in the test''s Mathematics section', 'For the Bachelor in Mathematical and Computing Sciences for Artificial Intelligence specifically, applicants must "obtain at least 11 points out of 24 in the ''Mathematics'' area" of the Bocconi online test, in addition to clearing the overall minimum score of 17.', true, 'high', 'https://www.unibocconi.it/en/applying-bocconi/bachelor-and-law-programs/application-and-admissions/online-bocconi-test', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'english_proficiency', 'TOEFL iBT 90, IELTS 6.5, or Cambridge CPE/CAE required for English-taught bachelor programmes', '"TOEFL iBT 90 (internet based), or IELTS 6.5 (Academic version, Overall Band Score), or University of Cambridge Certificate of Proficiency in English (CPE) or Certificate in Advanced English (CAE)."', true, 'high', 'https://www.tudelft.nl/en/education/admission-and-application/bsc-international-diploma/1-admission-requirements/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'english_proficiency', 'Nationals of the USA, UK, Ireland, Australia, New Zealand and Canada, and diplomas with English as a final exam subject, are exempt', '"Nationals from the USA, U.K., Ireland, Australia, New Zealand and Canada" are exempt from the English proficiency test requirement, as are applicants holding certain diplomas (Surinam VWO, International Baccalaureate, European Baccalaureate, or equivalent European pre-university certificates) "with English as a final examination subject."', true, 'high', 'https://www.tudelft.nl/en/education/admission-and-application/bsc-international-diploma/1-admission-requirements/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'required_subject', 'Mathematics is required for all BSc programmes', 'TU Delft''s admission requirements page lists Mathematics as a required subject examination, applicable to "All BSc programmes."', true, 'high', 'https://www.tudelft.nl/en/education/admission-and-application/bsc-international-diploma/1-admission-requirements/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'required_subject', 'Physics is required for all BSc programmes except Computer Science and Engineering, and Applied Mathematics', 'TU Delft''s admission requirements page lists Physics as required "for All BSc programmes, except Computer Science and Engineering, and Applied Mathematics."', true, 'high', 'https://www.tudelft.nl/en/education/admission-and-application/bsc-international-diploma/1-admission-requirements/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'curriculum', 'A secondary school diploma equivalent to the Dutch pre-university (VWO) diploma is required', '"A secondary school diploma which is considered to be equivalent to the Dutch pre-university (VWO) diploma" is required for admission to BSc programmes.', true, 'high', 'https://www.tudelft.nl/en/education/admission-and-application/bsc-international-diploma/1-admission-requirements/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'minimum_grade', 'Australian applicants need an ATAR of at least 86 (example: ACT Senior Secondary Certificate)', 'For applicants with an Australian Year 12 diploma specifically: "One of the below mentioned Australia year 12 diplomas in combination with an ATAR score of at least 86. For all diplomas Mathematics and, depending on the BSc program of your choice, Physics, Chemistry, Biology are mandatory subjects." Example given for the Australian Capital Territory: "Australian Capital Territory Senior Secondary Certificate with at least 120 standard units, 3 major T courses and 1 minor T course, including Mathematical Methods T (major), and if required by the program, Physics T, Chemistry T, Biology T. All mandatory subjects need to be major courses." The source page breaks this down further per Australian state/territory.', true, 'high', 'https://www.tudelft.nl/en/education/admission-and-application/bsc-international-diploma/admission-requirements/country-specific-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'minimum_grade', 'Ontario (Canada) applicants need an OSSD with a U/M-course average of at least 80%', 'For applicants with an Ontario Secondary School Diploma specifically: "Ontario Secondary School Diploma (OSSD) with at least 6 grade 12 U or M courses, including at least 4-U-courses in academic subjects with an average score of at least 80%. For all TU Delft BSc programs a U course in mathematics is required whereas for most BSc programs a U course in physics is required. Some BSc programs require a U course in chemistry and or biology."', true, 'high', 'https://www.tudelft.nl/en/education/admission-and-application/bsc-international-diploma/admission-requirements/country-specific-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'minimum_grade', 'Chinese Gaokao applicants need a minimum overall score of 75%, and at least 75% in each mandatory subject', 'For applicants presenting the Chinese Senior Middle School diploma plus Gaokao specifically: "Senior middle school graduation certificate ... and the National College Entrance Examinations (Gaokao) in Mathematics. Depending on the BSc program of your choice, Physics, Chemistry, Biology are mandatory subjects in the Gaokao as well. The Gaokao must be obtained with a minimum overall score (CGPA) of 75% and with a score of at least 75% for each of the mandatory subjects."', true, 'high', 'https://www.tudelft.nl/en/education/admission-and-application/bsc-international-diploma/admission-requirements/country-specific-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'minimum_grade', 'American High School Diploma applicants need at least 4 AP exams, each scored at least 3', 'Applicants are "eligible for admission if you hold an American High School diploma from an accredited high school with at least 4 College Board AP exams," and "all exams require a minimum score of 3." Regional accreditation required.', true, 'high', 'https://www.tudelft.nl/en/education/admission-and-application/bsc-international-diploma/admission-requirements/diploma-with-additional-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'required_subject', 'Only IB Mathematics "Analysis & Approaches HL" is accepted; the IB Career-related Programme (IBCP) is not accepted', '"TU Delft only accepts the Mathematics course ''Analysis & Approaches HL''. NB. we do not accept students with an IBCP." Required subject combinations vary by programme, e.g. Aerospace Engineering: "Mathematics: AA HL + Physics HL"; Computer Science & Engineering: "Mathematics: AA HL"; Nanobiology: "Mathematics: AA HL + Physics HL + Biology HL + Chemistry SL".', true, 'high', 'https://www.tudelft.nl/en/education/admission-and-application/bsc-international-diploma/admission-requirements/diploma-with-additional-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'minimum_grade', 'GCE A-Level applicants need six GCSEs and three-to-four A-Levels graded A*-C', '"six GCSE in different subjects with grades *A - C" plus "at least three and in some cases four A levels with grades *A - C." Required A-Level subjects vary by programme, e.g. Aerospace Engineering: "Mathematics + Physics"; Earth, Climate and Technology: "Mathematics + Physics + Chemistry".', true, 'high', 'https://www.tudelft.nl/en/education/admission-and-application/bsc-international-diploma/admission-requirements/diploma-with-additional-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'standardized_test', 'Computer Science & Engineering applicants are tested on Mathematics and Systematic Reasoning & Logical Thinking', 'For the numerus fixus Matching & Selection procedure for the Computer Science & Engineering bachelor (this program only, not confirmed universal): "For the selection part all candidates will be tested on two selection criteria: 1. Mathematics 2. Systematic Reasoning & Logical Thinking." A separate "Matching" component must also be completed to receive a ranking number but does not influence ranking.', true, 'high', 'https://www.tudelft.nl/en/onderwijs/opleidingen/bachelors/computer-science-and-engineering/bachelor-of-computer-science-and-engineering/from-application-to-enrollment/selection-procedure', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('b3e69141-b7fb-474a-a8df-44804aedd5f5', 'standardized_test', 'CSE selection-test score determines a lottery category; final ranking is randomly drawn within that category', '"Your test score determines in which lottery category you are placed... for the English track, the 210 highest-scoring candidates are placed in category 1, the next 540 candidates are placed in category 2, and the rest is placed in category 3." "Your final ranking number is a unique number and is assigned completely random from the drawn numbers in the category in which you were placed." Scoped to the 2026-2027 admission cycle (590 new bachelor students: 345 English track, 245 Bilingual track).', true, 'high', 'https://www.tudelft.nl/en/onderwijs/opleidingen/bachelors/computer-science-and-engineering/bachelor-of-computer-science-and-engineering/from-application-to-enrollment/selection-procedure', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('5df0803b-98e5-4484-9798-c59dddcddb84', 'english_proficiency', 'All admitted students must demonstrate English proficiency through one of: BUEPT, TOEFL iBT, or IELTS Academic.', 'As the language of instruction is English, all admitted students must demonstrate English proficiency through one of the following: BUEPT (Boğaziçi University English Proficiency Test), administered by the School of Foreign Languages (YADYOK); TOEFL iBT; or IELTS Academic. All documents must be validated by YADYOK for TOEFL and IELTS.', true, 'high', 'https://intl.bogazici.edu.tr/?q=required-documents-undergraduate-application', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('5df0803b-98e5-4484-9798-c59dddcddb84', 'english_proficiency', 'TOEFL iBT — Minimum Total Score: 79, TWE (Writing): 22', 'TOEFL iBT Minimum Total Score: 79. TWE (Writing): 22. TOEFL Home Edition not accepted. All exam scores are valid for two years.', true, 'high', 'https://intl.bogazici.edu.tr/?q=required-documents-undergraduate-application', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('5df0803b-98e5-4484-9798-c59dddcddb84', 'english_proficiency', 'IELTS Academic — Overall Score: 6.5, Writing: 6.5', 'IELTS Academic Overall Score: 6.5. Writing: 6.5. IELTS Online not accepted. All exam scores are valid for two years.', true, 'high', 'https://intl.bogazici.edu.tr/?q=required-documents-undergraduate-application', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('5df0803b-98e5-4484-9798-c59dddcddb84', 'english_proficiency', 'Students not meeting the requirement will attend the English Preparatory Program at YADYOK.', 'Students not meeting the requirement will attend the English Preparatory Program at YADYOK. Exemptions: Applicants may be exempt from the proficiency requirement based on other criteria. Please consult YADYOK for details and obtain an official exemption confirmation.', true, 'high', 'https://intl.bogazici.edu.tr/?q=required-documents-undergraduate-application', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('5df0803b-98e5-4484-9798-c59dddcddb84', 'required_subject', 'GCE A Levels: Applicants must receive an A grade in three subjects relevant to the program applied.', 'GCE A Levels: Applicants must receive an A grade in three subjects relevant to the program applied. Note: Three A grades will be considered sufficient for application eligibility. However, the relevance of the subjects to the program applied for will be determined by the corresponding department during the evaluation process.', true, 'high', 'https://intl.bogazici.edu.tr/?q=required-documents-undergraduate-application', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('6e66c4e7-9d04-4262-8d33-27df6ca04c7d', 'minimum_grade', 'Students without a listed exam score may be evaluated on national diploma grades, but with a significantly lesser chance of admission.', 'Although you may apply with your national diploma grades and high school transcript, students who cannot provide any of the listed exams may also be evaluated based on their national high school diploma grades and other credentials but will typically have a significantly lesser chance of admission. Exam scores older than 2 years at the time of application will not be accepted. However, there is no binding time constraint for diploma grades.', true, 'medium', 'https://registrar.ku.edu.tr/en/admission/international-students/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('6e66c4e7-9d04-4262-8d33-27df6ca04c7d', 'standardized_test', 'It is not sufficient to have proficiency in English — applicants must also satisfy minimum scores or diploma grades in an accepted exam/diploma.', 'It is not sufficient to have proficiency in English. International students are also expected to satisfy the minimum acceptable scores or diploma grades in the exams or diplomas listed in the Acceptable Exams and Diplomas and Minimum Eligibility Scores and Grades section.', true, 'high', 'https://registrar.ku.edu.tr/en/admission/international-students/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('6e66c4e7-9d04-4262-8d33-27df6ca04c7d', 'standardized_test', 'Applying with a test score or diploma not on the accepted list significantly diminishes your admission chances.', 'Copy of one of the acceptable international test score reports or diploma grades, if available. Applying with a test score or a diploma not included in this list significantly diminishes your admission chances.', false, 'high', 'https://registrar.ku.edu.tr/en/admission/international-students/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('6e66c4e7-9d04-4262-8d33-27df6ca04c7d', 'english_proficiency', 'Since English is the medium of instruction at Koç University, it is essential that you demonstrate competence in the language.', 'Students who submit a valid English Proficiency Exam Result and/or completed the last 3 years of high school in an English-official-language country are exempted from the English Language Center (ELC) and begin undergraduate courses directly. It is not sufficient to have proficiency in English alone -- applicants must also satisfy the minimum acceptable score/grade for one of the listed exams/diplomas.', true, 'high', 'https://registrar.ku.edu.tr/en/admission/international-students/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('6e66c4e7-9d04-4262-8d33-27df6ca04c7d', 'english_proficiency', 'Koç University English Proficiency Exam (KUEPE): a score of 60 or above promotes students to their academic programs.', 'Koç University English Proficiency Exam (KUEPE), administered by the ELC. Students who achieve a KUEPE score of 60 or above will be promoted to their academic programs.', true, 'high', 'https://registrar.ku.edu.tr/en/admission/international-students/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('6e66c4e7-9d04-4262-8d33-27df6ca04c7d', 'english_proficiency', 'TOEFL iBT — 80 total/20 writing (exams before Jan 21, 2026); 4.5 total (exams on/after Jan 21, 2026)', 'Exams Taken Before January 21, 2026: 80 (total) / 20 (minimum writing) (Valid 2 years); Home Edition and My Best Score not accepted. Exams Taken on or After January 21, 2026: 4.5 (total, new ETS scale) (Valid 2 years); Home Edition and My Best Score not accepted.', true, 'high', 'https://registrar.ku.edu.tr/en/admission/international-students/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('6e66c4e7-9d04-4262-8d33-27df6ca04c7d', 'english_proficiency', 'External Exam Scores — YDS/E-YDS 80/100; PTE Academic 67/90; CAE/CPE Grade C; e-TEP 74; Oxford Test of English Advanced 141–145/170', 'YDS / E-YDS: 80/100 (Valid 5 years). PTE Academic: 67/90 (Valid 2 years). CAE/CPE: min grade C (Valid 3 years). e-TEP: 74 total (Valid 2 years). Oxford Test of English Advanced: 141-145/170, all sections same day (Valid 2 years).', true, 'high', 'https://registrar.ku.edu.tr/en/admission/international-students/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('6e66c4e7-9d04-4262-8d33-27df6ca04c7d', 'essay', 'Motivation letter — a written expression of your qualities as an applicant and why you''re an appropriate candidate for their program.', 'Motivation letter: a written expression of your qualities as an applicant, often a very important way for faculty members to understand why you are an appropriate candidate for their program.', true, 'high', 'https://registrar.ku.edu.tr/en/admission/international-students/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('6e66c4e7-9d04-4262-8d33-27df6ca04c7d', 'recommendation', 'At least (2) letters of recommendation in English.', 'At least (2) letters of recommendation in English.', true, 'high', 'https://registrar.ku.edu.tr/en/admission/international-students/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('6e66c4e7-9d04-4262-8d33-27df6ca04c7d', 'international_requirement', 'Students who cannot apply as international students: Turkish citizens who completed their entire high school education in Türkiye or the TRNC.', 'Eligible: foreign nationals who did not complete secondary education in Türkiye (limited exceptions); Turkish citizens who completed secondary education entirely abroad (except TRNC); certain TRNC citizens with GCE AL or TR-YÖS. Not eligible: Turkish citizens who completed high school entirely in Türkiye or TRNC; most TRNC citizens; dual nationals whose first nationality by birth is Turkish (unless high school completed entirely abroad).', true, 'high', 'https://registrar.ku.edu.tr/en/admission/international-students/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('a971d87b-8868-4fc4-9929-150323cb53f7', 'standardized_test', 'Harvard requires the SAT or ACT to meet its standardized testing requirement.', 'Harvard requires the SAT or ACT to meet its standardized testing requirement. In exceptional cases when those tests are not accessible, one of the following can meet the requirement: AP exam results, IB Actual or Predicted Scores, GCSE/A-Level Actual or Predicted Results, National Leaving Exams Results (externally assessed) or Predictions. Students who have other forms of testing listed above (AP, IB, GCSE, or National Leaving Exams) are still expected to take an SAT or ACT and submit those scores, if financial considerations or test availability would not limit their ability to do so.', true, 'high', 'https://college.harvard.edu/admissions/apply/application-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('a971d87b-8868-4fc4-9929-150323cb53f7', 'standardized_test', 'Applicants may provide self-reported SAT and ACT test scores.', 'Applicants may provide self-reported SAT and ACT test scores (including Subject Tests, Advanced Placement, IB, etc.). Admitted students who decide to enroll at Harvard College will be required to submit official test scores.', true, 'high', 'https://college.harvard.edu/admissions/apply/application-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('a971d87b-8868-4fc4-9929-150323cb53f7', 'standardized_test', 'There are no score cutoffs, and we do not admit "by the numbers."', 'There are no score cutoffs, and we do not admit "by the numbers." For the ACT, we will evaluate your highest composite score and any other scores you choose to share with us. We take into account your educational background when reviewing your scores.', false, 'high', 'https://college.harvard.edu/admissions/apply/application-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('a971d87b-8868-4fc4-9929-150323cb53f7', 'minimum_grade', 'There is no formula for gaining admission to Harvard.', 'There is no formula for gaining admission to Harvard. Academic accomplishment in high school is important, but the Admissions Committee also considers many other criteria, such as community involvement, leadership and distinction in extracurricular activities, and personal qualities and character.', false, 'high', 'https://college.harvard.edu/resources/faq/what-admissions-criteria-do-you-use', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('a971d87b-8868-4fc4-9929-150323cb53f7', 'minimum_grade', 'High school grades in a rigorous academic program can also be helpful in assessing readiness for college courses...', 'High school grades in a rigorous academic program can also be helpful in assessing readiness for college courses, but the thousands of secondary schools around the country and the world employ various high school curricula and a wide range of grading systems - and some have no grades at all. Given the wide variation in how students prepare for Harvard -- as well as the fact that most applicants and admitted students have outstanding academic records -- it is difficult for high school grades to differentiate individual applications. That does not mean that high school grades are unimportant.', false, 'high', 'https://college.harvard.edu/admissions/apply/application-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('a971d87b-8868-4fc4-9929-150323cb53f7', 'curriculum', 'An ideal four-year preparatory program includes four years of English, with extensive practice in writing...', 'There is no single academic path we expect all students to follow, but the strongest applicants take the most rigorous secondary school curricula available to them. An ideal four-year preparatory program includes four years of English, with extensive practice in writing; four years of math; four years of science: biology, chemistry, physics, and an advanced course in one of these subjects; three years of history, including American and European history; and four years of one foreign language.', false, 'high', 'https://college.harvard.edu/resources/faq/are-there-secondary-school-course-requirements-admission', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('a971d87b-8868-4fc4-9929-150323cb53f7', 'prerequisite_coursework', 'Calculus is not a requirement for admission to Harvard.', 'Applicants to Harvard should excel in a challenging high school math sequence corresponding to their educational interests and aspirations. We recommend that applicants take four years of math courses in high school. Students'' math records are viewed holistically, and no specific course is required. Specifically, calculus is not a requirement for admission to Harvard -- many programs of study at Harvard do not require knowledge of calculus.', false, 'high', 'https://college.harvard.edu/admissions/apply/application-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('a971d87b-8868-4fc4-9929-150323cb53f7', 'english_proficiency', 'First-year and transfer applicants are not required to take an English proficiency exam, but you may submit scores if you wish to do so.', 'A strong knowledge of English is essential for successful study at Harvard, including the ability to understand and express thoughts quickly and clearly. First-year and transfer applicants are not required to take an English proficiency exam, but you may submit scores if you wish to do so. English language proficiency examinations such as the TOEFL, IELTS and Duolingo cannot be used to meet the standardized testing requirement, though students are welcome to submit them for review as part of their application materials.', false, 'high', 'https://college.harvard.edu/admissions/apply/international-applicants', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('a971d87b-8868-4fc4-9929-150323cb53f7', 'essay', 'Five required short-answer questions, each with a 150 word limit.', 'Complete the Harvard Questions with the Common Application. This includes five required short-answer questions, each with a 150 word limit, covering: how life experiences enable you to contribute to Harvard; a time you strongly disagreed with someone about an idea; extracurricular/employment/travel/family responsibilities that shaped you; how you hope to use your Harvard education in the future; top 3 things your roommates might like to know about you.', true, 'high', 'https://college.harvard.edu/admissions/apply/application-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('a971d87b-8868-4fc4-9929-150323cb53f7', 'recommendation', 'Ask two teachers in different academic subjects who know you well to complete the Teacher Recommendation forms.', 'Ask two teachers in different academic subjects who know you well to complete the Teacher Recommendation forms (evaluation form + letter). The secondary school report is a required form submitted by your school counselor, including the academic transcript(s), a letter of recommendation, and a school profile (if available).', true, 'high', 'https://college.harvard.edu/admissions/apply/application-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('a971d87b-8868-4fc4-9929-150323cb53f7', 'interview', 'Your application is considered complete without an interview and will receive a full and thorough evaluation.', 'Applicants are assigned interviews at the discretion of the Admissions Committee, based partly on availability of alumni in your local area. Nearly 10,000 alumni/ae volunteers help recruit students, but most areas do not have capacity to interview all applicants. Your application is considered complete without an interview and will receive a full and thorough evaluation.', false, 'high', 'https://college.harvard.edu/admissions/application-process/what-we-look/interviews', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('a971d87b-8868-4fc4-9929-150323cb53f7', 'international_requirement', 'A lack of financial resources or need for financial aid are not impediments to your admission.', 'A lack of financial resources or need for financial aid are not impediments to your admission. Our aid is entirely need-based, and eligibility is determined in the same manner for all admitted students. Foreign students have the same access to financial aid funding as U.S. citizens.', true, 'high', 'https://college.harvard.edu/financial-aid/how-aid-works/fact-sheet', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('42a2cc3c-ee6b-42e7-8812-822718f68094', 'standardized_test', 'For first-year and transfer applicants seeking to enroll in fall 2027, Princeton remains test optional.', 'For first-year and transfer applicants seeking to enroll in fall 2027, Princeton remains test optional. Students who opt to apply to Princeton in 2026-27 cycle without an ACT or SAT score will not be at a disadvantage in our process.', false, 'high', 'https://admission.princeton.edu/apply/standardized-testing', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('42a2cc3c-ee6b-42e7-8812-822718f68094', 'standardized_test', 'Princeton will return to requiring standardized testing for undergraduate admission beginning with the 2027-28 admission cycle.', 'Princeton will return to requiring standardized testing for undergraduate admission beginning with the 2027-28 admission cycle. First-year and transfer applicants seeking to enroll in fall 2028 will need to submit either SAT or ACT scores. The decision follows a review of five years of test-optional data, which found academic performance at Princeton was stronger for students who chose to submit test scores than for those who did not.', true, 'high', 'https://admission.princeton.edu/apply/standardized-testing', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('42a2cc3c-ee6b-42e7-8812-822718f68094', 'standardized_test', 'There are no minimum test score requirements for admission.', 'Standardized testing is just one element of the University''s comprehensive and holistic application review. There are no minimum test score requirements for admission. All information in each student''s application is considered in the student''s individual context.', false, 'high', 'https://admission.princeton.edu/apply/standardized-testing', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('42a2cc3c-ee6b-42e7-8812-822718f68094', 'minimum_grade', 'Are minimum grade-point averages, class ranks, or test scores required for admission? No.', 'Are minimum grade-point averages, class ranks, or test scores required for admission? No. We consider all of these measures, but only within the context of each applicant''s school and situation. These criteria, while important, do not by themselves provide a complete picture of each student''s academic accomplishment or potential.', false, 'high', 'https://admission.princeton.edu/faqs', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('42a2cc3c-ee6b-42e7-8812-822718f68094', 'minimum_grade', 'We do not expect you or your school to provide a conversion or grade-point average (GPA) if this is not a standard practice provided by your school.', 'Your transcript is evaluated within the context of your educational system and school curriculum. If your school or national education system does not provide internal grades, you are not required to report them. We also do not expect you or your school to provide a conversion or GPA if this is not a standard practice provided by your school or education system.', false, 'high', 'https://admission.princeton.edu/apply/international-students', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('42a2cc3c-ee6b-42e7-8812-822718f68094', 'curriculum', 'Four years of English (including continued practice in writing).', 'This is not a list of admission requirements -- we give full consideration to students who don''t have access to all of these courses. If possible, we expect students will complete: Four years of English; four years of mathematics (including calculus for students interested in engineering); four years of one language; at least two years of laboratory science (including physics and chemistry for students interested in engineering); at least two years of history. Most candidates have had some study in the visual or performing arts.', false, 'high', 'https://admission.princeton.edu/apply/before-you-apply', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('42a2cc3c-ee6b-42e7-8812-822718f68094', 'english_proficiency', 'If English is not your native language and you are attending a school where English is not the language of instruction, you must take the TOEFL, IELTS Academic, DET or PTE Academic.', 'You must take TOEFL, IELTS Academic, Duolingo English Test (DET), or PTE Academic if English is not your native language and you attend a school where English is not the language of instruction. Not required if English is your native language or you''ve spent at least three years at a secondary school where English is the primary language of instruction.', true, 'high', 'https://admission.princeton.edu/apply/international-students', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('42a2cc3c-ee6b-42e7-8812-822718f68094', 'essay', 'What academic areas most pique your curiosity, and how do the programs offered at Princeton suit your particular interests?', 'As a research institution that also prides itself on its liberal arts curriculum, Princeton allows students to explore areas across the humanities and the arts, the natural sciences, and the social sciences. What academic areas most pique your curiosity, and how do the programs offered at Princeton suit your particular interests? (250 words or fewer.) B.S.E. applicants instead answer a parallel prompt about engineering interest.', true, 'high', 'https://admission.princeton.edu/apply/princeton-specific-questions', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('42a2cc3c-ee6b-42e7-8812-822718f68094', 'essay', 'Reflect on how your lived experiences will impact the conversations you will have in the classroom, the dining hall or other campus spaces.', 'Princeton values community and encourages respectful conversations that can expand perspectives and challenge ideas. As a prospective community member, reflect on how your lived experiences will impact the conversations you will have in the classroom, the dining hall or other campus spaces. What lessons have you learned in life thus far? What will your classmates learn from you? (400-500 words.)', true, 'high', 'https://admission.princeton.edu/apply/princeton-specific-questions', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('42a2cc3c-ee6b-42e7-8812-822718f68094', 'supplemental_requirement', 'We ask all students to submit a graded written paper for consideration as part of their application to Princeton.', 'The paper should be from an academic course in English, social studies or history, from the last three years of secondary school, including senior year -- a paper, essay, research paper, or in-class essay exam. Princeton is most interested in expository, thesis-driven analytical writing rather than science research, creative writing, personal narratives, or data-analysis-focused papers. Papers should be at least one page in length and originally written in English (no translations).', true, 'high', 'https://admission.princeton.edu/apply/graded-written-paper', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('42a2cc3c-ee6b-42e7-8812-822718f68094', 'recommendation', 'Please ask two of your teachers who have taught you in higher level courses... in different academic areas of study to complete and send the teacher recommendation forms.', 'Ask two teachers who taught you in higher-level courses (e.g., AP, IB Higher/Standard Level, A-Levels) in different academic areas -- core academic areas such as English, language, humanities, social sciences, natural sciences, or math -- to complete and send the teacher recommendation forms via the Common Application.', true, 'high', 'https://admission.princeton.edu/apply/application-checklist', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('42a2cc3c-ee6b-42e7-8812-822718f68094', 'interview', 'Princeton offers optional alumni interviews.', 'Interviews take place after the Admission Office has received your application. You may opt out in the Princeton-specific Questions with no disadvantage to your application. Princeton cannot guarantee every applicant will receive an interview -- depends on alumni availability in your area. Princeton does not offer on-campus interviews.', false, 'high', 'https://admission.princeton.edu/apply/application-checklist', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('361848d4-2f1c-4d47-b515-be8c2584c79c', 'standardized_test', 'A minimum total score of 1200 (SAT I)', 'SAT I: A minimum total score of 1200 (with an additional minimum "Math" score of 700 out of 800 for the Faculty of Engineering, Faculty of Architecture, and scientific programs offered by the Faculty of Arts and Sciences).', true, 'high', 'https://iso.metu.edu.tr/en/system/files/odtu_iso_requirements.pdf', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('361848d4-2f1c-4d47-b515-be8c2584c79c', 'standardized_test', 'A minimum score of 27 out of 36 (ACT)', 'American College Testing (ACT): A minimum score of 27 out of 36.', true, 'high', 'https://iso.metu.edu.tr/en/system/files/odtu_iso_requirements.pdf', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
