  ('361848d4-2f1c-4d47-b515-be8c2584c79c', 'english_proficiency', 'IELTS exams taken on or after 24 December 2022 will not be accepted', 'According to the University Senate Decision, dated December 23, 2022, decision no. 6., IELTS exams taken on or after the 24th of December 2022 will not be anymore accepted.', true, 'high', 'https://iso.metu.edu.tr/en/english-proficiency', '2026-09-03'::timestamptz, 'verified_current', 'fresh', 'inverted_recency', '{"direction":"not_valid_on_or_after","boundaryDate":"2022-12-24"}'::jsonb);
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('361848d4-2f1c-4d47-b515-be8c2584c79c', 'english_proficiency', 'Minimum score for exemption from Basic English (undergraduate)', 'Equivalence table for exemption from the Basic English preparatory program (undergraduate): METU English Proficiency Exam (EPE) score of 60 = TOEFL IBT 75 = PTE Academic 55 (for scores obtained before 12.11.2024) / PTE Academic 65 (for scores obtained after 12.11.2024).', true, 'high', 'https://oidb.metu.edu.tr/en/equivalence-table-english-language-exams-recognized-metu-undergraduate-and-graduate-students', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('361848d4-2f1c-4d47-b515-be8c2584c79c', 'english_proficiency', 'Submitting an English proficiency score is not obligatory for the application', 'Submitting an English Proficiency Exam result is not obligatory for the application itself; however, admitted students who do not submit a valid TOEFL, IELTS, or PTE ACADEMIC score during registration must take the ODTÜ English Proficiency Exam, and those who do not achieve the required score attend the English Preparatory Class at the Department of Basic English for one year before starting undergraduate courses.', false, 'medium', 'https://iso.metu.edu.tr/en/english-proficiency', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('361848d4-2f1c-4d47-b515-be8c2584c79c', 'supplemental_requirement', 'Exam results such as TR-YÖS, SAT, QUDURAT, and TQDK are valid for two years', 'Exam results such as TR-YÖS, SAT, QUDURAT, and TQDK are valid for two years. Documents holding the status of a high-school diploma are valid with any date.', true, 'high', 'https://iso.metu.edu.tr/en/application-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
