  ('361848d4-2f1c-4d47-b515-be8c2584c79c', 'international_requirement', 'Eligibility defined by YÖK''s Principles Governing International Student Admissions', 'Only the candidates whose eligibility is defined in the "Principles Governing International Student Admissions" drawn up by the Council of Higher Education can apply to these quotas.', true, 'medium', 'https://iso.metu.edu.tr/en/who-can-apply', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
