insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('4cae2d57-9ddb-482d-a010-37e4efd6dc00', 'english_proficiency', 'IELTS is not accepted in Turkey', '"Do you accept IELTS?" — "No, IELTS is not accepted in Turkey. This is a decision taken by the YOK (Council of Higher Education), binding for all Turkish universities."', true, 'high', 'http://iro.sabanciuniv.edu/en/degree-students/frequently-asked-questions/english-language-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('4cae2d57-9ddb-482d-a010-37e4efd6dc00', 'english_proficiency', 'You do not have to provide a TOEFL score, but you must provide an English proficiency document', '"Do I need to take TOEFL?" — "You do not have to provide a TOEFL score, yet, you have to provide an English Proficiency document to be exempt from the English Prep School." Students without a recognized certificate are automatically registered for the Sabancı University English Language Assessment Exam (ELAE), an in-house exam organized by the School of Languages that "has two stages"; those who do not reach the required score in ELAE Stage II are placed in the English Language Preparatory Program according to their level.', true, 'high', 'http://iro.sabanciuniv.edu/en/degree-students/frequently-asked-questions/english-language-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('4cae2d57-9ddb-482d-a010-37e4efd6dc00', 'international_requirement', 'Not currently enrolled in or a graduate of a secondary institution in Türkiye', 'International students are eligible provided that they are not currently enrolled in or graduates of secondary education (high school) institutions in Türkiye, except those who enroll in Embassy Schools and International Private Education Institutions in the MOBİS system, or those brought to the country within the framework of a project conducted by the Ministry of National Education.', true, 'medium', 'https://iro.sabanciuniv.edu/en/application-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('4cae2d57-9ddb-482d-a010-37e4efd6dc00', 'application_deadline', 'Early Application Deadline: March 14, 2026', 'Early Application Deadline: March 14, 2026. Application Deadline: August 28, 2026 (Online application form closes at 16:00 Turkish time).', true, 'high', 'https://iro.sabanciuniv.edu/en/how-to-apply', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'standardized_test', 'We require the SAT or the ACT for both prospective first-year and transfer students.', 'We require the SAT or the ACT for both prospective first-year and transfer students.', true, 'high', 'https://mitadmissions.org/apply/firstyear/tests-scores/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'standardized_test', 'We do not have cutoff or recommended scores for the ACT or SAT', 'We do not have cutoff or recommended scores for the ACT or SAT as scores are evaluated within an applicant''s context.', false, 'high', 'https://mitadmissions.org/apply/firstyear/tests-scores/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'standardized_test', 'Standardized tests help us identify socioeconomically disadvantaged students who lack access to advanced coursework', 'Our research shows standardized tests help us better assess the academic preparedness of all applicants, and also help us identify socioeconomically disadvantaged students who lack access to advanced coursework or other enrichment opportunities that would otherwise demonstrate their readiness for MIT.', true, 'high', 'https://mitadmissions.org/blogs/entry/we-are-reinstating-our-sat-act-requirement-for-future-admissions-cycles/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'standardized_test', 'We believe a requirement is more equitable and transparent than a test-optional policy.', 'We believe a requirement is more equitable and transparent than a test-optional policy.', true, 'high', 'https://mitadmissions.org/blogs/entry/we-are-reinstating-our-sat-act-requirement-for-future-admissions-cycles/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'english_proficiency', 'We strongly recommend English proficiency exam results if you''ve used English for fewer than five years', 'For non-native English speakers, we strongly recommend providing the results of an English proficiency exam if you have been using English for fewer than five years or do not speak English at home or in school, so that we may consider that information alongside the rest of your application.', false, 'high', 'https://mitadmissions.org/apply/firstyear/tests-scores/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'english_proficiency', 'English proficiency exam minimum/recommended scores (TOEFL, IELTS, PTE, Cambridge, Duolingo)', 'Per MIT''s published table of minimum/recommended scores: TOEFL (before 1/21/26) minimum 90, recommended 100; TOEFL (on/after 1/21/26, new 1-6 scale) minimum 5, recommended 5.5; IELTS minimum 7, recommended 7.5; Pearson Test of English (PTE) Academic minimum 65, recommended 70; Cambridge English Qualifications (C1 Advanced or C2 Proficiency) minimum 185, recommended 190; Duolingo English Test (DET) minimum 120, recommended 125.', false, 'high', 'https://mitadmissions.org/apply/firstyear/tests-scores/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'curriculum', 'Students are much more likely to succeed at MIT when they''ve taken math throughout high school, including exposure to calculus', 'Students are much more likely to succeed at MIT academically when they have taken math classes throughout high school, including at least some exposure to the foundations of calculus by the time they graduate.', false, 'high', 'https://mitadmissions.org/apply/prepare/foundations/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'curriculum', 'Most well-prepared students will have taken at least some physics, chemistry, and/or biology by the end of high school', 'Most students who are well-prepared for MIT will have taken at least some physics, chemistry, and/or biology by the end of high school. We recommend that you take at least introductory coursework across all three subjects, if available.', false, 'high', 'https://mitadmissions.org/apply/prepare/foundations/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'curriculum', 'We recommend at least some challenging courses in English, history, economics, music, and/or foreign languages', 'We recommend that you pursue at least some challenging courses in areas like English, history, economics, music, and/or foreign languages. Students who take few or no challenging courses in these areas may not be well-prepared—or well-matched—for the MIT education.', false, 'high', 'https://mitadmissions.org/apply/prepare/foundations/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'curriculum', 'There are no specific high school courses in these fields that we require', 'There are no specific high school courses in these fields that we require. (Stated regarding humanities, arts, and social sciences preparation specifically.)', false, 'high', 'https://mitadmissions.org/apply/prepare/foundations/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'curriculum', 'Non-American curriculum students should take the most challenging math/science available and demonstrate English proficiency', 'For students not in an American curriculum: you should be taking the most challenging math and science courses available at your school, and you should demonstrate proficiency in English, the language of instruction at MIT.', false, 'high', 'https://mitadmissions.org/apply/prepare/foundations/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'minimum_grade', 'We accept whatever grades your school can make available, considered in the context of your school', 'We accept whatever grades your school can make available to us and consider them in the context of your school, whether that be letter grades, numerical grades, narrative assessments, or something else.', true, 'high', 'https://mitadmissions.org/help/faq/what-if-i-dont-have-letter-grades-for-some-of-my-coursework-or-have-chosen-to-take-a-class-pass-fail/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'international_requirement', 'Our admissions process is need-blind for all students, foreign and domestic.', 'Our admissions process is need-blind for all students, foreign and domestic.', true, 'high', 'https://mitadmissions.org/help/faq/need-blind-admissions/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'international_requirement', 'MIT considers any student without US citizenship or permanent residency an international applicant', 'MIT considers any student who does not hold United States citizenship or permanent residency to be an international applicant, regardless of where they live or attend school.', true, 'high', 'https://mitadmissions.org/apply/firstyear/international/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('03167d0c-2315-49e3-a37e-f9c9c7d2d27c', 'application_deadline', 'Early Action applications due November 1; Regular Action applications due January 4', 'Early Action (EA) applications are due November 1 and admission decisions are released in mid-December. Regular Action (RA) applications are due January 4 and admission decisions are released in mid-March. NO YEAR STATED on the source page -- treat as an annually-recurring date, not a specific-cycle date, unless re-confirmed for a specific year.', true, 'high', 'https://mitadmissions.org/apply/firstyear/deadlines-requirements/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'minimum_grade', 'Offers for students studying A-levels range between A*A*A and AAA depending on the course', '"Offers for students studying A-levels range between A*A*A and AAA depending on the course. If a practical component forms part of any of your science A‐levels used to meet your offer, we expect you to pass it. Each course page gives details of specific subject and grade requirements."', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/admissions-requirements/uk-qualifications', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'minimum_grade', 'Higher GCSE grades can help make an application more competitive; successful applicants typically have a high proportion of 7, 8 and 9 grades', '"GCSEs (or IGCSEs) will be taken into account when we consider your application but they are just one aspect that we look at. Higher grades at GCSE can help to make your application more competitive, and successful applicants typically have a high proportion of 7,8 and 9 grades. However, we do look at GCSE grades in context where possible."', false, 'medium', 'https://www.ox.ac.uk/admissions/undergraduate/courses/admissions-requirements/uk-qualifications', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'minimum_grade', 'Oxford''s admissions processes use a range of evidence including prior achievement and predicted grades', '"Oxford''s admissions processes use a range of evidence about applicant performance and potential, including information from UCAS forms, the personal statement and reference, prior achievement and predicted grades. Oxford also considers the results of any admissions tests where relevant, and interview performance for those shortlisted." The same page adds: "We would not advise that UCAS''s entry grades data is used to predict the likelihood of being admitted to Oxford."', true, 'medium', 'https://www.ox.ac.uk/admissions/undergraduate/courses/admissions-requirements/uk-qualifications', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'minimum_grade', 'Economics and Management — A*AA including Mathematics at grade A or above', '"A-levels: A*AA including Mathematics at grade A or above." Course-specific entry requirement for Economics and Management.', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/economics-and-management', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'minimum_grade', 'Economics and Management — IB 39 points (including core points) with 766 at Higher Level', '"International Baccalaureate (IB): 39 (including core points) with 766 at HL." Course-specific IB equivalent for Economics and Management.', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/economics-and-management', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'minimum_grade', 'Computer Science — A*AA, including A*A in Maths and Further Maths if available (in any order)', '"A-levels: A*AA, including A*A in Maths and Further Maths if available (in any order)." Course-specific entry requirement for Computer Science.', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/computer-science', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'minimum_grade', 'Computer Science — IB 39 points (including core points) with 766 at HL, the 7 must be in HL Mathematics', '"International Baccalaureate (IB): 39 (including core points) with 766 at HL (the 7 must be in HL Mathematics)." Course-specific IB equivalent for Computer Science.', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/computer-science', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'minimum_grade', 'Medicine — A*AA in three A-levels, excluding Critical Thinking and Thinking Skills, with at least an A in Chemistry and one other science/Maths subject', '"A-levels: A*AA in three A-levels (excluding Critical Thinking and Thinking Skills) taken in the same academic year. Applicants are required to achieve at least a grade A in both Chemistry and at least one of Biology, Physics, Mathematics or Further Mathematics." IB equivalent: "International Baccalaureate (IB): 39 (including core points) with 766 at HL. Applicants are required to take Chemistry and at least one of Biology, Physics or Mathematics to Higher Level."', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/medicine', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'minimum_grade', 'Medicine — no formal GCSE requirement, but applicants should have at least grade C/4 in Biology, Physics and Mathematics', '"There are no formal GCSE requirements for Medicine. However, in order to be adequately equipped for the application process and for the academic demands of the course, applicants will need to have received a basic education in Biology, Physics and Mathematics. For example, students should have received at least a grade C/4 at GCSE, Intermediate 2 or Standard grade (Credit) or equivalent. The GCSE Dual Award Combined Sciences is also appropriate."', false, 'medium', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/medicine', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'minimum_grade', 'Mathematics — A*A*A with the A*s in Mathematics and Further Mathematics if available', '"A-levels: A*A*A with the A*s in Mathematics and Further Mathematics (if available). For those for whom Further Mathematics is not available: either A*AAa with A* in Mathematics and a in AS-level Further Mathematics or A*AA with A* in Mathematics." IB equivalent: "International Baccalaureate (IB): 39 (including core points) with 766 at HL (the 7 must be in Higher Level Mathematics)."', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/mathematics', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'minimum_grade', 'Law (Jurisprudence) — AAA at A-level, or IB 38 points (including core points) with 666 at Higher Level', '"A-levels: AAA." "International Baccalaureate (IB): 38 (including core points) with 666 at HL." This is the lowest A-level/IB tier found among the Oxford courses researched, versus A*A*A/39 for Mathematics and Medicine, directly illustrating genuine course-to-course variation.', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/law-jurisprudence', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'curriculum', 'Computer Science — Mathematics required to A-level; Further Mathematics highly recommended (96% of accepted students took it)', '"Required: Mathematics to A-level (A* or A grade), Advanced Higher (A grade), Higher Level in the IB (score 7) or another equivalent. Recommended: Further Mathematics A-level is highly recommended... If your school offers Further Mathematics A-Level we expect you to have taken it. From 2022-25, 96% of A-level students offered places for Computer Science courses took Further Mathematics to A-level."', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/computer-science', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'curriculum', 'Medicine — Chemistry and at least one of Biology, Physics, Mathematics or Further Mathematics required', '"Required: Chemistry and at least one of Biology, Physics, Mathematics or Further Mathematics. Recommended: Further subjects in Biology, Physics, Mathematics or Further Mathematics."', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/medicine', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'curriculum', 'General Studies, Critical Thinking and Thinking Skills, and Global Perspectives and Research are not accepted A-levels', '"Providing that any specific subject requirements have been met, all A-levels are approved for admissions purposes, with the exception of: General Studies - not accepted by any course; Critical Thinking and Thinking Skills - not accepted by Biomedical Sciences or Medicine; Global Perspectives and Research - not accepted by any course. Maths and Further Maths are viewed as separate A-levels."', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/admissions-requirements/uk-qualifications', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'standardized_test', 'TARA — Test of Academic Reasoning for Admissions, required for Economics and Management and related courses', '"All applicants must take the Test of Academic Reasoning for Admissions (TARA) as part of their application. All Oxford applicants must take all three modules (Critical Thinking, Problem Solving and the Writing Task)." Also required for PPE, History and Economics, History and Politics, Human Sciences, Psychology (Experimental), Psychology Philosophy and Linguistics, and Foundation Year (PPE).', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/economics-and-management', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'standardized_test', 'TMUA — Test of Mathematics for University Admission, required for Computer Science and Mathematics courses', '"All applicants must take the Test of Mathematics for University Admission (TMUA) as part of their application. All Oxford applicants must take both Paper 1 (Applications of Mathematical Knowledge) and Paper 2 (Mathematical Reasoning)." Also required for Computer Science and Philosophy, Mathematics and Statistics, Mathematics and Computer Science, and Mathematics and Philosophy.', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/computer-science', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'standardized_test', 'UCAT — University Clinical Aptitude Test, required for Medicine', '"All applicants must take the University Clinical Aptitude Test (UCAT) as part of their application. Separate registration for this test is required and it is the responsibility of the applicant to ensure that they are registered for the test."', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/medicine', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'standardized_test', 'LNAT — Law National Admissions Test, required for Law (Jurisprudence)', '"All applicants must take the Law National Admissions Test (LNAT) as part of their application." Also required for Law with Law Studies in Europe and Foundation Year (Law).', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/law-jurisprudence', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('e5164eb3-88c1-4ecc-81d7-d591ea0c34ea', 'standardized_test', 'ESAT — Engineering and Science Admissions Test, required for Physics and related science/engineering courses', '"All applicants must take the Engineering and Science Admissions Test (ESAT) as part of their application. All Oxford applicants must take the following three modules: Mathematics 1, Mathematics 2, Physics." Also required for Biomedical Sciences, Engineering Science, Physics and Philosophy, and Foundation Year (Engineering).', true, 'high', 'https://www.ox.ac.uk/admissions/undergraduate/courses/course-listing/physics', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'minimum_grade', 'You need to have top grades to study at the University of Cambridge', '"You need to have top grades to study at the University of Cambridge. You''ll need to check the entry requirements for your course before you apply. You may need to have qualifications in a particular subject and achieve certain grades. The entry requirements for your course may differ between Cambridge Colleges."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/apply/before/entry-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'minimum_grade', 'Minimum IB offer levels are 41-42 points out of 45, with 776 in Higher Level subjects', '"Minimum offer levels are 41-42 points out of 45, with 776 in Higher Level subjects. The following Colleges usually make IB offers above the minimum offer level: Churchill, Corpus Christi, and Selwyn. Some Colleges may ask you to achieve 777 or a higher points total."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/apply/before/accepted-qualifications', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'minimum_grade', 'There are no GCSE (or equivalent) requirements for entry to Cambridge', '"There are no GCSE (or equivalent) requirements for entry to Cambridge. Our minimum offers are based on A levels and other Level 3 qualifications. We will look at your GCSE results as an indicator of your academic performance. But this will be within the context of the performance of the school/college where you achieved your GCSEs."', false, 'high', 'https://www.undergraduate.study.cam.ac.uk/apply/before/accepted-qualifications', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'minimum_grade', 'Minimum offer level for Economics — A level A*A*A, IB 41-42 points with 776 at Higher Level', '"Minimum offer level: A level: A*A*A. IB: 41-42 points, with 776 at Higher Level." Course-specific for Economics. This identical baseline was independently confirmed verbatim on Computer Science and Medicine course pages too -- Cambridge holds a common "minimum offer level" for several courses, with differentiation via required subjects/college overlays rather than a different baseline grade per course.', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/courses/economics-ba-hons', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'minimum_grade', 'Minimum offer level for English — A level A*AA, IB 41-42 points with 776 at Higher Level', '"Minimum offer level: A level: A*AA. IB: 41-42 points, with 776 at Higher Level." One A* lower than the A*A*A baseline for Economics/Computer Science/Medicine -- genuine course-to-course variation (the IB figure of 41-42/776 stays constant across every course page checked).', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/courses/english-ba-hons', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'minimum_grade', 'Mathematics — minimum offer A*A*A / IB 41-42 (776), plus STEP grade 1 in two papers', '"Minimum offer level: A level: A*A*A. IB: 41-42 points, with 776 at Higher Level. STEP: all Colleges usually require at least grade 1 in two STEP papers (STEP 2 and 3)."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/courses/mathematics-ba-hons-mmath', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'minimum_grade', 'Most Economics entrants actually achieved at least A*A*A* (80%); majority of IB entrants achieved at least 44 points', '"Most Economics students (who had studied A levels and started at Cambridge in 2018, 2019 and 2023) achieved at least A*A*A* (80% of entrants)... The majority of students who studied IB achieved at least 44 points overall." Historical attainment data about admitted students, NOT a stated requirement -- the official minimum offer is A*A*A (A-level) / 41-42 points (IB); admits typically exceed this.', false, 'medium', 'https://www.undergraduate.study.cam.ac.uk/courses/economics-ba-hons', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'required_subject', 'Economics — Mathematics required at A level/IB Higher Level', '"To apply to any of our Colleges for Economics, you will need an A level/IB Higher Level (or the equivalent) in: Mathematics. If you''re studying IB, we ask for Analysis and Approaches for this course."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/courses/economics-ba-hons', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'required_subject', 'Computer Science — Mathematics required; Further Mathematics required to AS/A level if offered by the school', '"To apply to any of our Colleges for Computer Science, you will need A levels/IB Higher Levels (or the equivalent) in: Mathematics; Further Mathematics to AS or A level if your school offers it. Colleges usually require A* in Mathematics and/or Further Mathematics. Colleges may also require an A*/7 in specific subjects (usually Chemistry or Physics, if taken)."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/courses/computer-science-ba-hons-meng', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'required_subject', 'Medicine — Chemistry plus one or two other science/Maths subjects, depending on College', '"To apply to any of our Colleges for Medicine you will need A Levels/IB Higher Levels (or the equivalent) in: Chemistry; one or two other science or mathematics subject from: Mathematics, Biology or Human Biology, Physics, Further Mathematics. The number needed depends on which College you apply to. Colleges usually require A* in Chemistry."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/courses/medicine-mb-bchir', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'required_subject', 'English — English Literature (or English Literature and Language) required', '"To apply to any of our Colleges for English, you will need: A level/IB Higher Level (or the equivalent) in English Literature or A level (or the equivalent) in English Literature and Language."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/courses/english-ba-hons', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'standardized_test', 'TMUA — Test of Mathematics for University Admission, required for Economics, Computer Science and Mathematics', '"All applicants for Economics are required to take the Test of Mathematics for University Admission (TMUA) at an authorised assessment centre. You must register in advance for this test." Confirmed identically required for Computer Science and Mathematics on their respective course pages.', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/courses/economics-ba-hons', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'standardized_test', 'UCAT — University Clinical Aptitude Test, required for Medicine; no minimum threshold score', '"You will need to take the University Clinical Aptitude Test. You will need to register in advance for this test. We assess applicants through a mixture of academic record, UCAT and interviews. There is no minimum threshold for UCAT score."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/courses/medicine-mb-bchir', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'standardized_test', 'STEP Mathematics — required as part of almost all conditional offers for Mathematics', '"STEP Mathematics is used to assess aptitude for university study in mathematical subjects. It''s used as part of almost all conditional offers from Cambridge for Mathematics. Some Colleges require or may require STEP for other courses needing strong mathematical ability." On the Mathematics page: "All Colleges usually require at least grade 1 in one STEP paper (STEP 2 or 3). The minimum offer level is grade 1 in STEP 2 and 3. You don''t need to take STEP before you apply."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/apply/before/accepted-qualifications', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'standardized_test', 'CSAT — Computer Sciences Aptitude Test, required only for Peterhouse and Trinity applicants', '"If you''re applying to Peterhouse or Trinity you will also need to take the Computer Sciences Aptitude Test (CSAT)." College-specific -- not a university-wide Computer Science requirement (TMUA is the university-wide test).', true, 'medium', 'https://www.undergraduate.study.cam.ac.uk/courses/computer-science-ba-hons-meng', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'english_proficiency', 'Expected to achieve a good C1 standard (CEFR) in all four competencies by the time you start', '"As a guide, you would be expected to achieve a good C1 standard within the Common European Framework for Languages (CEFR) in all four competencies by the time you start at Cambridge University. Commonly, this is demonstrated by one of the qualifications listed below."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/apply/before/entry-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'english_proficiency', 'IELTS Academic — normally a minimum overall grade of 7.5, usually with 7.0 or above in each element', '"Minimum English language requirements: IELTS Academic – normally a minimum overall grade of 7.5, usually with 7.0 or above in each element."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/apply/before/entry-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'english_proficiency', 'For interview, English ability equivalent to at least IELTS Academic 6.5 overall (no element below 6.0) is recommended', '"To take part in an interview, we recommend that, at the point of application, your English language ability is equivalent to at least IELTS Academic 6.5 overall, with no element below 6.0. If you are then offered a place, you will need to go on to meet our minimum English language requirements for admission."', false, 'high', 'https://www.undergraduate.study.cam.ac.uk/apply/before/entry-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'english_proficiency', 'Cambridge English C2 Proficiency (min 200, no element below 185) and C1 Advanced (min 193, no element below 185) accepted', '"Cambridge English at an appropriate standard: C2 Proficiency – accepted with a minimum overall score of 200, with no element lower than 185. C1 Advanced – accepted with a minimum overall score of 193, with no element lower than 185, alongside other evidence of competence in English."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/apply/before/entry-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'supplemental_requirement', 'The Colleges do not routinely admit students under the age of 18', '"The Colleges do not routinely admit students under the age of 18. If you''ll be under 18 when you join us, you should talk to your shortlisted College(s) as early as possible to discuss your application. If you''ll be under the age of 16 on admission, you may need to meet additional requirements and restrictions to comply with legislation."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/apply/before/entry-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'supplemental_requirement', 'Medicine applicants cannot apply if they will not be 18 years old on 1 November of year 1', '"You can''t apply to this course if you: will not be 18 years old on 1 November of year 1. This is due to national restrictions [or] have failed or been excluded from another medical school."', true, 'high', 'https://www.undergraduate.study.cam.ac.uk/courses/medicine-mb-bchir', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('135ab387-945b-40a7-836a-bda0e60a5583', 'international_requirement', 'We accept a wide variety of qualifications from all over the world and expect students to be achieving the highest grades', '"We accept a wide variety of qualifications from all over the world and expect students to be achieving the highest grades. Minimum offer levels for a range of qualifications including the European Baccalaureate, International A Levels and the International Baccalaureate can be viewed on our qualifications we accept page."', true, 'medium', 'https://www.undergraduate.study.cam.ac.uk/international-students/international-entry-requirements', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('0b204add-2507-45b0-85f4-917e725b16c2', 'curriculum', 'Breadth of subjects is valued by our selectors', 'Breadth of subjects is valued by our selectors and therefore subjects with significantly overlapping curricula should be avoided where possible, for example Accounting and Business Studies for Warwick Business School courses.', true, 'high', 'https://warwick.ac.uk/study/undergraduate/applying/entry-requirements/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('0b204add-2507-45b0-85f4-917e725b16c2', 'minimum_grade', 'Typical offers are listed under each course entry, not university-wide', 'Typical offers for common qualifications such as A levels, the IB, Scottish Highers and BTECs are listed under each course entry on the Undergraduate Study pages. Some courses have GCSE requirements above the University minimum, noted on the relevant course-specific entry requirements page. Warwick does not state one universal offer grade across all courses.', true, 'medium', 'https://warwick.ac.uk/study/undergraduate/applying/entry-requirements/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('0b204add-2507-45b0-85f4-917e725b16c2', 'prerequisite_coursework', 'Grade C/4 minimum in GCSE English Language and Mathematics', 'All applicants must possess a minimum level of a pass at Grade C / Grade 4 or above in both GCSE English Language and Mathematics, or an equivalent qualification.', true, 'high', 'https://warwick.ac.uk/study/undergraduate/applying/entry-requirements/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('0b204add-2507-45b0-85f4-917e725b16c2', 'minimum_grade', 'Mathematics BSc/MMath — A* in Maths, A* in Further Maths plus A in a third subject', 'Typical A-level offer for Mathematics (BSc/MMath) applicants who sit TMUA: A* in Maths, A* in Further Maths plus A in a third subject at A-level. Applicants taking STEP instead of TMUA require the same A-level grades but must also achieve grade 2 in any STEP paper. The page frames this as the offer for "strong TMUA performers," implying banding by test performance rather than one fixed offer for all applicants — exact banding detail wasn''t stated on this page.', true, 'medium', 'https://warwick.ac.uk/fac/sci/maths/studywithus/ug/our-offer/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('0b204add-2507-45b0-85f4-917e725b16c2', 'entrance_exam', 'Mathematics applicants must take TMUA or STEP on top of A-levels', 'To study Mathematics BSc or MMath, applicants must take an entry exam on top of their A levels, either TMUA or STEP. All applicants will typically be required to take TMUA or STEP, except for applicants who are eligible for a Contextual Offer.', true, 'high', 'https://warwick.ac.uk/fac/sci/maths/studywithus/ug/our-offer/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('0b204add-2507-45b0-85f4-917e725b16c2', 'minimum_grade', 'Computer Science BSc — A*A*A to include A* in Mathematics', 'A*A*A to include A* in Mathematics. A-level Mathematics or equivalent is therefore required for this programme; Further Maths is not essential but is a highly recommended subject choice. The typical contextual offer is A*AA including A in Mathematics.', true, 'high', 'https://warwick.ac.uk/study/undergraduate/courses/bsc-computer-science/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('0b204add-2507-45b0-85f4-917e725b16c2', 'minimum_grade', 'Computer Science BSc — IB 39 points with 7,6,6 including HL Mathematics', '39 with 7, 6, 6 in three Higher Level subjects to include 7 in Higher Level Mathematics ("Analysis and Approaches" only). The typical contextual offer is 38 including 6 in Higher Level Mathematics ("Analysis and Approaches" only).', true, 'high', 'https://warwick.ac.uk/study/undergraduate/courses/bsc-computer-science/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('0b204add-2507-45b0-85f4-917e725b16c2', 'entrance_exam', 'Computer Science — TMUA required except for Contextual Offer applicants', 'All 2026-27 applicants will be required to take TMUA except for applicants who are eligible for a Contextual Offer. Applicants who do not take TMUA and who are not eligible for a Contextual Offer may not be considered for an offer.', true, 'high', 'https://warwick.ac.uk/study/undergraduate/courses/bsc-computer-science/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('0b204add-2507-45b0-85f4-917e725b16c2', 'minimum_grade', 'BSc Economics (L100) — A*AA including A in Mathematics', 'A*AA including A in Mathematics. A-level Mathematics or equivalent is required for this programme; Further Maths and Economics are not essential, though they are accepted subject choices. Only the top three grades (including Mathematics) are counted. A contextual offer of AAB including A in Maths is available for eligible applicants.', true, 'high', 'https://warwick.ac.uk/study/undergraduate/courses/bsc-economics', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('0b204add-2507-45b0-85f4-917e725b16c2', 'entrance_exam', 'Economics — TMUA is optional, not required', 'Optionally, applicants are encouraged to sit the Test of Mathematics for University Admission (TMUA). TMUA scores may be used as a factor in determining which applicants receive an offer for Economics L100, but applicants who do not sit TMUA will still be given full consideration.', false, 'high', 'https://warwick.ac.uk/study/undergraduate/courses/bsc-economics', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'minimum_grade', 'Standard offers between AAA and A*A*A across Imperial''s courses', 'Standard offers between AAA and A*A*A: please see individual courses for specific requirements. Some courses require higher entry requirements than the minimum standard listed; specific course requirements are provided on the relevant course page.', true, 'medium', 'https://www.imperial.ac.uk/study/apply/undergraduate/entry-requirements/accepted-qualifications/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'minimum_grade', 'IB overall scores of 38-42, with 6-7 in relevant higher-level subjects', 'Overall scores of 38-42, with scores of 6-7 in relevant subjects at higher level, across Imperial''s undergraduate courses generally. See individual course pages for the specific score required.', true, 'medium', 'https://www.imperial.ac.uk/study/apply/undergraduate/entry-requirements/accepted-qualifications/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'entrance_exam', 'Some departments require both minimum entry requirements and an admission test', 'Some departments require both minimum entry requirements and an admission test. Imperial uses four tests: the Engineering and Science Admissions Test (ESAT), the Test of Mathematics for University Admissions (TMUA), the University Clinical Aptitude Test (UCAT), and the Graduate Medical School Admissions Test (GAMSAT). Scores are considered alongside other parts of the UCAS application, like the personal statement, when deciding whether to invite an applicant to interview or make an offer. Achieving a high score does not necessarily mean an applicant will be offered a place, while a low score does not mean the application will be unsuccessful.', true, 'high', 'https://www.imperial.ac.uk/study/apply/undergraduate/process/admissions-tests/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'minimum_grade', 'Medicine MBBS/BSc — A*AA including A* and A in Biology and Chemistry', 'A*AA to include A* and A in Biology and Chemistry (the A* in either subject), and A in a third subject. All qualifications must be taken in the same sitting. General Studies and Critical Thinking are not accepted.', true, 'high', 'https://www.imperial.ac.uk/study/courses/undergraduate/medicine/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'minimum_grade', 'Medicine MBBS/BSc — IB 38 points including 6 in HL Biology and 6 in HL Chemistry', '38 points to include 6 in Biology at higher level and 6 in Chemistry at higher level.', true, 'high', 'https://www.imperial.ac.uk/study/courses/undergraduate/medicine/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'standardized_test', 'Medicine applicants must take the UCAT', 'You will need to take the University Clinical Aptitude Test (UCAT) to study this course. You must book the test yourself and must only take it once in an admissions cycle. No offers are made without applicants attending a competitive interview.', true, 'high', 'https://www.imperial.ac.uk/study/courses/undergraduate/medicine/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'standardized_test', 'Medicine UCAT minimum threshold total score, as published for 2026 entry', 'For 2026 entry the minimum UCAT threshold total score was 2320 for Home applicants and 2170 for Contextual applicants; a minimum in each subsection also applies alongside the total. This is a specific admissions-cycle figure, not a fixed permanent threshold — applicants should verify the current cycle''s cut-off on Imperial''s site, as UCAT thresholds are recalculated annually.', true, 'high', 'https://www.imperial.ac.uk/study/courses/undergraduate/medicine/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'minimum_grade', 'Physics BSc — A*A*A including A* in Mathematics and A* in Physics', 'A*A*A to include A* in Mathematics, A* in Physics, and A in another subject (Further Mathematics is recommended, but not essential). General Studies and Critical Thinking are not accepted. If made an offer, applicants must also achieve a pass in the science practical endorsement in all science subjects forming part of the offer.', true, 'high', 'https://www.imperial.ac.uk/study/courses/undergraduate/physics-bsc/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'entrance_exam', 'Physics applicants must sit three ESAT modules', 'You must sit the Engineering and Science Admissions Test (ESAT) as part of the application process for this course. To be eligible for selection, you will need to sit three ESAT modules: Mathematics 1, Mathematics 2, and Physics.', true, 'high', 'https://www.imperial.ac.uk/study/courses/undergraduate/physics-bsc/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'minimum_grade', 'Computing BEng — minimum standard A*A*A to A*AAA, A* in Mathematics required', 'Minimum entry standard A*A*A – A*AAA, to include A* in Mathematics, plus A*, A in two further subjects or AAA in three further subjects (Further Mathematics preferred). Typical offer is A*A*A for applicants studying three A-levels or A*A*AA for four A-levels. ICT, Business Studies, General Studies and Critical Thinking are not accepted.', true, 'high', 'https://www.imperial.ac.uk/study/courses/undergraduate/computing-beng/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'minimum_grade', 'Computing BEng — IB minimum 41 points, typical 42, including 7 in HL Maths', 'Minimum entry standard is 41 points to include 7 in Mathematics at higher level and 7 in another relevant subject at higher level. The typical offer is 42 points.', true, 'high', 'https://www.imperial.ac.uk/study/courses/undergraduate/computing-beng/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'entrance_exam', 'Computing applicants must sit the TMUA', 'You must sit the Test for Mathematics for University Admission (TMUA) as part of the application process for this course. The TMUA is a computer-based, multiple-choice test that tests mathematical thinking and reasoning skills.', true, 'high', 'https://www.imperial.ac.uk/study/courses/undergraduate/computing-beng/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'minimum_grade', 'Economics, Finance and Data Science BSc — A*AA including A* in Mathematics', 'A*AA, with A* in Mathematics and AA in two other subjects (Further Mathematics and/or Economics are useful, but not required). General Studies and Critical Thinking are not accepted. Either IB Mathematics Analysis and Approaches or Applications and Interpretation is accepted at higher level, with no preference between them.', true, 'high', 'https://www.imperial.ac.uk/study/courses/undergraduate/economics-finance-data-science/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'entrance_exam', 'Economics, Finance and Data Science applicants must sit the TMUA', 'You must sit the Test of Mathematics for University Admission (TMUA) as part of the application process for this course. Imperial takes a holistic approach when reviewing applications — academic performance, subject choices, personal statement, reference, and TMUA score are all considered, with no minimum TMUA score and no fixed weighting applied to components.', true, 'high', 'https://www.imperial.ac.uk/study/courses/undergraduate/economics-finance-data-science/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'english_proficiency', 'Standard English requirement — IELTS 6.5 overall / TOEFL 92 overall', 'Standard level: IELTS 6.5 overall (minimum 6.0 in all elements); TOEFL iBT 92 overall (minimum 20 in all elements). Which level (Standard or Higher) applies depends on the specific course.', true, 'high', 'https://www.imperial.ac.uk/study/apply/english-language/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'english_proficiency', 'Higher English requirement — IELTS 7.0 overall / TOEFL 100 overall', 'Higher level: IELTS 7.0 overall (minimum 6.5 in all elements); TOEFL iBT 100 overall (minimum 22 in all elements). Courses such as Physics BSc and Economics, Finance and Data Science BSc specify that applicants must meet the Higher level requirement.', true, 'high', 'https://www.imperial.ac.uk/study/apply/english-language/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d4544b9f-82fb-4563-b48a-346287e4b4d3', 'english_proficiency', 'GCSE English equivalent — Grade 5 for 2026 entry (Grade 6 for Medicine)', 'For 2025 entry, Grade 6 in GCSE English Language satisfied both Standard and Higher requirements. For 2026 entry, Home students need Grade 5 in English Language for all courses except MBBS Medicine, which requires Grade 6. This is a recently changed policy — the grade threshold differs by entry year, so it should be re-verified against the live page for whichever cycle a given student is applying to.', true, 'high', 'https://www.imperial.ac.uk/study/apply/english-language/', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'standardized_test', 'Caltech faculty did not decide to require a minimum score for the SAT or ACT; there is no cut-off score', 'Very intentionally, Caltech faculty did not decide to require a minimum score for the SAT or ACT. There is no preferred exam and there is no cut-off score.', false, 'high', 'https://www.admissions.caltech.edu/apply/first-year-applicants/standardized-tests', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'english_proficiency', 'The English proficiency exam must be taken prior to the application deadline.', 'The English proficiency exam must be taken prior to the application deadline.', true, 'high', 'https://www.admissions.caltech.edu/apply/first-year-applicants/international-applicants', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'curriculum', 'Four years of math, including one year of calculus', 'Four years of math, including one year of calculus.', true, 'high', 'https://www.admissions.caltech.edu/apply/first-year-applicants/academic-requirements-for-first-year-applicants', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'curriculum', 'One year of physics', 'One year of physics.', true, 'high', 'https://www.admissions.caltech.edu/apply/first-year-applicants/academic-requirements-for-first-year-applicants', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
