insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'minimum_grade', 'Holistic review does not mean academic preparation is optional', 'Holistic review does not mean that every element of an application carries equal weight or that academic preparation is optional. Students must first demonstrate that they are prepared to thrive in Caltech''s demanding curriculum.', true, 'high', 'https://www.admissions.caltech.edu/apply/what-we-look-for/how-we-review', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'minimum_grade', 'We assess preparation through the full academic record, including proof of mastery of calculus, chemistry, and physics', 'We assess that preparation through the full academic record, including proof of mastery of calculus, chemistry, and physics, the rigor and content of a student''s coursework, performance over time, depth of understanding, and other available evidence of mathematical and scientific readiness.', true, 'high', 'https://www.admissions.caltech.edu/apply/what-we-look-for/how-we-review', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, data_confidence, source_url, retrieved_at, verification_state, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'international_requirement', 'International applicants must apply for financial aid at the time they apply for admission', 'If you are an international applicant and plan to apply for financial aid at any time during your undergraduate career here, you must apply for it at the time that you apply for admission. If you do not apply for or receive financial aid for your first year, you may not apply for aid for any other academic period (exceptions may be made for citizens of Canada and Mexico).', true, 'high', 'https://www.admissions.caltech.edu/apply/first-year-applicants/international-applicants', '2026-09-03'::timestamptz, 'verified_current', 'fresh');
